
# ---------------
# filterSequences
# ---------------

test_that("filterSequences removes sequences with primer and extension errors.", {
  test.reads <- makeFakeSRQ(Biostrings::DNAStringSet(c(rep("", 33),  # WT            AGCGAATTAGAG
                                           rep("", 24),  # WT            CTCGAATTAGTA
                                           rep("", 11),  # 2 base change TTTAGCGCGTAG
                                           rep("", 8),       # -4, internal  GGCGTATTAACC
                                           rep("", 7),        # -5, 3' end    CATGTGGCACGC
                                           rep("", 6),  # +1 insertion  CTTATGACGCTC
                                           rep("", 4),  # +1 ins, 1 bc  TCCAGGGTATTC
                                           rep("", 8),       # f primer del  AATAAGTCATTA
                                           rep("", 4),      # r primer del  CCCATCACAAAG
                                           rep("", 5),   # umi error     GGCGTGAAAGAG
                                           rep("", 3),   # barcode error CCTAACTCAGGA
                                           rep("", 3),      # -4, +1        CTTAGGGCATGT
                                           rep("", 2)    # < reads       GTTATGTTGTTA
  )))
  test.filtered <- filterSequences(test.reads, test.settings)
  expect_true(class(test.filtered) == "ShortReadQ")
  expect_true(length(test.filtered) == 98)
  expect_true(length(unique(as.character(ShortRead::sread(test.filtered)))) == 9)
  expect_all_true(c("",
                    "",
                    "",
                    "",
                    "",
                    "",
                    "",
                    "",
                    ""
                    ) %in% as.character(ShortRead::sread(test.filtered)))
  expect_all_false(c("",
                     "",
                     "",
                     ""
                     ) %in% as.character(ShortRead::sread(test.filtered)))

})

test_that("sequenceTable returns the expected objects and results.", {
  test.reads <- makeFakeSRQ(Biostrings::DNAStringSet(c(rep("", 33),  # WT            AGCGAATTAGAG
                                           rep("", 24),  # WT            CTCGAATTAGTA
                                           rep("", 11),  # 2 base change TTTAGCGCGTAG
                                           rep("", 8),       # -4, internal  GGCGTATTAACC
                                           rep("", 7),        # -5, 3' end    CATGTGGCACGC
                                           rep("", 6),  # +1 insertion  CTTATGACGCTC
                                           rep("", 4),  # +1 ins, 1 bc  TCCAGGGTATTC
                                           rep("", 8),       # f primer del  AATAAGTCATTA
                                           rep("", 4),      # r primer del  CCCATCACAAAG
                                           rep("", 5),   # umi error     GGCGTGAAAGAG
                                           rep("", 3),   # barcode error CCTAACTCAGGA
                                           rep("", 3),      # -4, +1        CTTAGGGCATGT
                                           rep("", 2)    # < reads       GTTATGTTGTTA
  )))
  test.filtered <- filterSequences(test.reads, test.settings)
  expect_output(expect_no_error(sequenceTable(test.filtered, test.settings)))

  filter.counts <- c(Merged = 118L, Filtered = 98L)
  expect_output(test.seq <- sequenceTable(test.filtered, test.settings, filter.counts))

  expect_true(validObject(test.seq))

  expect_true(class(test.seq) == "tas.sequences")
  expect_true(class(test.seq@Table) == "data.frame")
  expect_all_true(class(test.seq@Supplemental) == c("data.table", "data.frame"))
  expect_true(class(test.seq@Alignments) == "list")
  expect_all_true(sapply(test.seq@Alignments, function(x){
    cl <- logical(length(x))
    for (i in 1:length(x)) {
      cl[i] <- class(x[[i]])
    }
    return(cl)
  }) == "PairwiseAlignmentsSingleSubject")
  expect_true(class(test.seq@ReadCounts) == "integer")

  expect_true(nrow(test.seq@Table) == 7)
  expect_all_true(test.seq@Table$Sequences == c("",
                                                "",
                                                "GTTCAACTGGTGGAAAGCGGCGGTGCTCTGGTACAACCGGGCGGTAGTCTGCGCCTGAGCTGTGCCGCAAGCGGTTTCCCAGTCAACCGCTACTCTATGCGTTGGTATCGCCAGGCGCCTGGTAAAGAACGTGAATGGGTTGCCGGCATGAGCAGTGCGGGCGATCGTTCTAGTTACGAGGACTCTGTTAAAGGTCGTTTTACAATTAGCCGTGATGATGCGCGCAATACCGTGTATCTGCAAATGAACAGTCTGAAGCCGGAGGACACCGCAGTATATTATTGCAATGTCAACGT----TTTGAATATTGGGGCCAGGGGACTCAGGTGACGGTGAGCTCT",
                                                "",
                                                "",
                                                "",
                                                "GTTCAACTGGTGGAAAGCGGCGGTGCTCTGGTACAACCGGGCGGTAGTCTGCGCCTGAGCTGTGCCGCAAGCGGTTTCCCAGTCAACCGCTACTCTATGCGTTGGTATCGCCAGGCGCCTGGTAAAGAACGTGAATGGGTTGCCGGCATGAGCAGTGCGGGCGATCGTTCTAGTTACGAGGACTCTGTTAAAGGTCGTTTTACAATTAGCCGTGATGATGCGCGCAATACCGTGTATCTGCAAATGAACAGTCTTGAAGCCGGAGGACACCGCAGTATATTATTGCAATGTCAACGT----TTTGAATATTGGGGCCAGGGGACTCAGGTGACGGTGAGCTCT"))
  expect_all_true(test.seq@Table$Count == c(2, 1, 1, 1, 1, 1, 1))
  expect_equal(test.seq@Table$Percent, c(25, 12.5, 12.5, 12.5, 12.5, 12.5, 12.5))
  expect_all_true(test.seq@Table$Indels == c("WT", "", "-4", "-5", "+1", "+1", "+1, -4"))
  expect_all_true(test.seq@Table$BasesChanged == c(0, 2, 0, 0, 0, 1, 0))
  expect_all_true(test.seq@Table$AA == c("VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVNVGFEYWGQGTQVTVSS",
                                         "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMRSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVNVGFEYWGQGTQVTVSS",
                                         "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVN-",
                                         "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVNVGFEYWGQGTQVTV-",
                                         "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAV+",
                                         "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAV+",
                                         "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNS+"))
  expect_all_true(test.seq@Table$ProteinMutation == c("WT", "S51R", "Indel", "Indel", "Indel", "Indel", "Indel"))

  expect_all_true(test.seq@Supplemental$UMIs[[1]] == c("AGCGAATTAGAG", "CTCGAATTAGTA"))
  expect_true(test.seq@Supplemental$UMIs[[2]] == "TTTAGCGCGTAG")
  expect_true(test.seq@Supplemental$UMIs[[3]] == "GGCGTATTAACC")
  expect_true(test.seq@Supplemental$UMIs[[4]] == "CATGTGGCACGC")
  expect_true(test.seq@Supplemental$UMIs[[5]] == "CTTATGACGCTC")
  expect_true(test.seq@Supplemental$UMIs[[6]] == "TCCAGGGTATTC")
  expect_true(test.seq@Supplemental$UMIs[[7]] == "CTTAGGGCATGT")
  expect_all_true(grepl("A90033:281:WB24762987th.Miseq:1:", test.seq@Supplemental$IDs))

  expect_true(length(test.seq@Alignments) == 2)
  expect_all_true(sapply(test.seq@Alignments, function(x){
    l <- logical(length(x))
    for (i in 1:length(x)) {
      l[i] <- length(x[[i]]) == 7
    }
    return(l)
  }))

  expect_all_true(test.seq@ReadCounts == c(118L, 98L, 8L, 7L))
})


