test_that("buildSequenceTable path for sequences without UMIs works", {
  expect_output(test.seq <- buildSequenceTable(test.settings))
  test.no.umis <- test.settings
  test.no.umis@ForwardExtensionType <- ""
  test.no.umis@ReverseExtensionType <- ""
  test.no.umis@ForwardPrimer <- stringr::str_c(test.no.umis@ForwardExtension,  test.no.umis@ForwardPrimer)
  test.no.umis@ReversePrimer <- stringr::str_c(test.no.umis@ReverseExtension,  test.no.umis@ReversePrimer)
  test.no.umis@ForwardExtension <- ""
  test.no.umis@ReverseExtension <- ""

  expect_output(test.seq.noumi <- buildSequenceTable(test.no.umis))
  expect_true(class(test.seq.noumi) == "tas.sequences")
  test.table <- getSequenceTable(test.seq.noumi)
  expect_equal(nrow(test.table), 7)
  expect_equal(test.table$Sequences, c("",
                                       "",
                                       "GTTCAACTGGTGGAAAGCGGCGGTGCTCTGGTACAACCGGGCGGTAGTCTGCGCCTGAGCTGTGCCGCAAGCGGTTTCCCAGTCAACCGCTACTCTATGCGTTGGTATCGCCAGGCGCCTGGTAAAGAACGTGAATGGGTTGCCGGCATGAGCAGTGCGGGCGATCGTTCTAGTTACGAGGACTCTGTTAAAGGTCGTTTTACAATTAGCCGTGATGATGCGCGCAATACCGTGTATCTGCAAATGAACAGTCTGAAGCCGGAGGACACCGCAGTATATTATTGCAATGTCAACGT----TTTGAATATTGGGGCCAGGGGACTCAGGTGACGGTGAGCTCT",
                                       "",
                                       "",
                                       "",
                                       "GTTCAACTGGTGGAAAGCGGCGGTGCTCTGGTACAACCGGGCGGTAGTCTGCGCCTGAGCTGTGCCGCAAGCGGTTTCCCAGTCAACCGCTACTCTATGCGTTGGTATCGCCAGGCGCCTGGTAAAGAACGTGAATGGGTTGCCGGCATGAGCAGTGCGGGCGATCGTTCTAGTTACGAGGACTCTGTTAAAGGTCGTTTTACAATTAGCCGTGATGATGCGCGCAATACCGTGTATCTGCAAATGAACAGTCTTGAAGCCGGAGGACACCGCAGTATATTATTGCAATGTCAACGT----TTTGAATATTGGGGCCAGGGGACTCAGGTGACGGTGAGCTCT")
               )
  expect_equal(test.table$AA, c("VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVNVGFEYWGQGTQVTVSS",
                                "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMRSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVNVGFEYWGQGTQVTVSS",
                                "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVN-",
                                "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAVYYCNVNVGFEYWGQGTQVTV-",
                                "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAV+",
                                "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNSLKPEDTAV+",
                                "VQLVESGGALVQPGGSLRLSCAASGFPVNRYSMRWYRQAPGKEREWVAGMSSAGDRSSYEDSVKGRFTISRDDARNTVYLQMNS+")
  )
  expect_equal(test.table$Count, c(59, 11, 8, 7, 6, 4, 3))
  expect_equal(test.table$Percent, c(60.2040816326531, 11.2244897959184, 8.16326530612245, 7.14285714285714, 6.12244897959184, 4.08163265306122, 3.06122448979592))
  expect_equal(test.table$Indels, c("WT", "", "-4", "-5", "+1", "+1", "+1, -4"))
  expect_equal(test.table$BasesChanged, c(0, 2, 0, 0, 0, 1, 0))
  expect_equal(test.table$ProteinMutation, c("WT", "S51R", "Indel", "Indel", "Indel", "Indel", "Indel"))
  expect_equal(getSequenceSupplemental(test.seq.noumi)[,-c("UMIs", "IDs")], getSequenceSupplemental(test.seq)[,-c("UMIs", "IDs")])
  expect_all_true(is.na(getSequenceSupplemental(test.seq.noumi)$UMIs))
  expect_equal(getAlignments(test.seq.noumi), getAlignments(test.seq))
  rc.noumi <- getFilterCounts(test.seq.noumi)
  expect_equal(rc.noumi[!names(rc.noumi) %in% "UMIs"], getFilterCounts(test.seq)[!names(getFilterCounts(test.seq)) %in% "UMIs"])
  expect_true(is.na(rc.noumi["UMIs"]))
})

